int[] m = {45, 80, 62, 30, 91, 55, 70, 48};
int sum = 0, max = m[0], min = m[0];
ArrayList<Integer> pass = new ArrayList<>();
for (int x : m) { sum += x; if (x > max) max = x; if (x < min) min = x; if (x > 50) pass.add(x); }
System.out.println((double) sum / m.length + " " + max + " " + min + " " + pass);
